        """Determine which extractors are enabled based on flags"""
        args = self.args
        any_enabled = any(getattr(args, flag, False) for flag in FLAG_TO_LABEL)

        if any_enabled:
            enabled = []
            for flag, label in FLAG_TO_LABEL.items():
                if getattr(args, flag, False):
                    for ext_label, ext_regex in EXTRACTORS:
                        if ext_label == label:
                            enabled.append((ext_label, ext_regex))
