        """Output a single result to stdout or CSV file"""
        args = self.args

        if args.output:
            self._write_csv_row(label, filename or "", line_num or 0, data)
            return

        hide_label = args.hide

        if args.display:
            if hide_label:
                if args.line and line_num is not None:
