    def _check_drop_filter(self, match_text):
        """Return True if match_text should be included"""
        if self.drop_regex and self.drop_regex.search(match_text):
            return False
        if self.filter_regex and not self.filter_regex.search(match_text):
            return False
        return True

    def process_line(self, line, filename=None, line_num=None):
        """Process a single line and output matching results"""
        args = self.args
        line_stripped = line.rstrip('\n')

        for label, pattern in self.enabled_extractors:
            regex = self.compiled_patterns[label]
            matches = list(regex.finditer(line_stripped))

            if not matches:
                continue

            if args.thorough:
                found_any = False
                for m in matches:
                    match_text = m.group()
                    if not self._check_drop_filter(match_text):
                        continue

                    found_any = True
                    if args.clean:
                        self._output_result(label, match_text, filename, line_num)
                    else:
                        self._output_result(label, line_stripped, filename, line_num)
                        self._output_result(label, match_text, filename, line_num)

                if found_any:
                    break
            else:
                first_match_text = matches[0].group()
                if not self._check_drop_filter(first_match_text):
                    continue

                if args.clean:
                    self._output_result(label, first_match_text, filename, line_num)
                else:
                    self._output_result(label, line_stripped, filename, line_num)

                break

    def process_stream(self, stream, filename=None):
        """Process all lines in a stream"""
        for line_num, line in enumerate(stream, 1):
            self.process_line(line, filename, line_num)

    def close(self):
        if self.output_file:
