    ("aws_keys",       r'aws_(?:access_key_id|secret_access_key)\s*=\s*\S+'),
    ("google",         r'"private_key_id":\s*"[a-fA-F0-9]{40}"'),
    ("srv_dns",        r'_\S+\s+\d+\s+IN\s+SRV\s+\d+\s+\d+\s+\d+\s+\S+'),
    ("social_security",r'\d{3}-\d{2}-\d{4}'),
    ("files",          r'[^:\n]*?\.(?:conf|cfg|log|sh|py|json|js|rb|xml|yaml|sql|exe|bat|db|gz|zip|rar|7z|jpeg|jpg|png|gif|bmp|pdf|txt|csv|doc|xls|tar|ps1|db3|mdb|ini)'),
]

