            data = json.load(f)
        if not isinstance(data, list):
            raise ValueError("Expected list")
        plugins = []
        for plugin in data:
            required = ('name', 'regex', 'label', 'args')
            if not all(k in plugin for k in required):
                raise ValueError(f"Missing required fields in plugin")
            plugins.append(plugin)
        return plugins
    except (json.JSONDecodeError, ValueError, TypeError):
        print("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.")
        while True:
