            header = "content_type, file, line, data"
        elif args.display:
            header = "content_type, file, data"
        elif args.line:
            header = "content_type, line, data"
        else:
            header = "content_type, data"
        self.output_file.write(header + "\n")
        self.csv_header_written = True

    def _write_csv_row(self, label, filename, line_num, data):
        if not self.csv_header_written:
            self._write_csv_header()

