def parse_args():
    """Parse command line arguments manually"""
    args_list = sys.argv[1:]

    class Args:
        file = ''
        add = ''
        update = ''
        remove = ''
        list = False
        clean = False
        directory = ''
        ignore = False
        line = False
        thorough = False
        display = False
        suppress = False
        drop = ''
        filter = ''
        hide = False
        output = ''
        time = False
        email = False
