        print("[-] Error: Failed to parse plugins.json. Please ensure all required fields are present.")
        while True:
            try:
                resp = input("[+] Do you want to exit? (y/n): ").strip().lower()
            except EOFError:
                resp = ''
            if resp == 'y':
                sys.exit(1)
            elif resp == 'n':
                return []
            else:
                print("[-] Invalid input. Please enter 'y' or 'n'.")


class DataSurgeon:
    def __init__(self, args):
        self.args = args
        self.enabled_extractors = self._get_enabled_extractors()
        self.compiled_patterns = {label: re.compile(pattern) for label, pattern in self.enabled_extractors}
        self.drop_regex = re.compile(args.drop) if args.drop else None
        self.filter_regex = re.compile(args.filter) if args.filter else None
        self.output_file = None
        self.csv_header_written = False

        if args.output:
            self.output_file = open(args.output, 'w')

    def _get_enabled_extractors(self):
        """Determine which extractors are enabled based on flags"""
        args = self.args
        any_enabled = any(getattr(args, flag, False) for flag in FLAG_TO_LABEL)

        if any_enabled:
            enabled = []
            for flag, label in FLAG_TO_LABEL.items():
                if getattr(args, flag, False):
                    for ext_label, ext_regex in EXTRACTORS:
                        if ext_label == label:
                            enabled.append((ext_label, ext_regex))
                            break
            return enabled
        else:
            return list(EXTRACTORS)

    def _write_csv_header(self):
        args = self.args
        if args.display and args.line:
            header = "content_type, file, line, data"
        elif args.display:
            header = "content_type, file, data"
        elif args.line:
            header = "content_type, line, data"
        else:
            header = "content_type, data"
        self.output_file.write(header + "\n")
        self.csv_header_written = True

    def _write_csv_row(self, label, filename, line_num, data):
        if not self.csv_header_written:
            self._write_csv_header()

        args = self.args
        if args.display and args.line:
            row = f"{label}, {filename}, {line_num}, {data}"
        elif args.display:
            row = f"{label}, {filename}, {data}"
        elif args.line:
            row = f"{label}, {line_num}, {data}"
        else:
            row = f"{label}, {data}"
        self.output_file.write(row + "\n")

    def _output_result(self, label, data, filename=None, line_num=None):
        """Output a single result to stdout or CSV file"""
        args = self.args

        if args.output:
            self._write_csv_row(label, filename or "", line_num or 0, data)
            return

        hide_label = args.hide

        if args.display:
            if hide_label:
                if args.line and line_num is not None:
                    output = f"file: {filename or ''} {data}, line: {line_num}"
                else:
                    output = f"file: {filename or ''} {data}"
            else:
                if args.line and line_num is not None:
                    output = f"{label}, file: {filename or ''} {data}, line: {line_num}"
                else:
                    output = f"{label}, file: {filename or ''} {data}"
        elif args.line and line_num is not None:
            if hide_label:
                output = f"{data}, line: {line_num}"
            else:
                output = f"{label}, {data}, line: {line_num}"
        else:
            if hide_label:
                output = data
            else:
                output = f"{label}: {data}"

        print(output)

    def _check_drop_filter(self, match_text):
        """Return True if match_text should be included"""
        if self.drop_regex and self.drop_regex.search(match_text):
            return False
        if self.filter_regex and not self.filter_regex.search(match_text):
            return False
        return True

    def process_line(self, line, filename=None, line_num=None):
        """Process a single line and output matching results"""
        args = self.args
        line_stripped = line.rstrip('\n')

        for label, pattern in self.enabled_extractors:
            regex = self.compiled_patterns[label]
            matches = list(regex.finditer(line_stripped))

            if not matches:
                continue

            if args.thorough:
                found_any = False
                for m in matches:
                    match_text = m.group()
                    if not self._check_drop_filter(match_text):
                        continue

                    found_any = True
                    if args.clean:
                        self._output_result(label, match_text, filename, line_num)
                    else:
                        self._output_result(label, line_stripped, filename, line_num)
                        self._output_result(label, match_text, filename, line_num)

                if found_any:
                    break
            else:
                first_match_text = matches[0].group()
                if not self._check_drop_filter(first_match_text):
                    continue

                if args.clean:
                    self._output_result(label, first_match_text, filename, line_num)
                else:
                    self._output_result(label, line_stripped, filename, line_num)

                break

    def process_stream(self, stream, filename=None):
        """Process all lines in a stream"""
        for line_num, line in enumerate(stream, 1):
            self.process_line(line, filename, line_num)

    def close(self):
        if self.output_file:
            self.output_file.close()


