def parse_args():
    """Parse command line arguments manually"""
    args_list = sys.argv[1:]

    class Args:
        file = ''
        add = ''
        update = ''
        remove = ''
        list = False
        clean = False
        directory = ''
        ignore = False
        line = False
        thorough = False
        display = False
        suppress = False
        drop = ''
        filter = ''
        hide = False
        output = ''
        time = False
        email = False
        phone = False
        hash = False
        ip_addr = False
        ipv6_addr = False
        mac_addr = False
        credit_card = False
        url = False
        files = False
        bitcoin = False
        aws = False
        google = False
        dns = False
        social = False
        help = False
        version = False

    args = Args()

    i = 0
    while i < len(args_list):
        arg = args_list[i]

        if arg in ('-h', '--help'):
            args.help = True
        elif arg in ('-V', '--version'):
            args.version = True
        elif arg in ('-f', '--file'):
            i += 1
            if i < len(args_list):
                args.file = args_list[i]
        elif arg == '--add':
            i += 1
            if i < len(args_list):
                args.add = args_list[i]
        elif arg == '--update':
            i += 1
            if i < len(args_list):
                args.update = args_list[i]
        elif arg == '--remove':
            i += 1
            if i < len(args_list):
                args.remove = args_list[i]
        elif arg == '--list':
            args.list = True
        elif arg in ('-C', '--clean'):
            args.clean = True
        elif arg == '--directory':
            i += 1
            if i < len(args_list):
                args.directory = args_list[i]
        elif arg == '--ignore':
            args.ignore = True
        elif arg in ('-l', '--line'):
            args.line = True
        elif arg in ('-T', '--thorough'):
            args.thorough = True
        elif arg in ('-D', '--display'):
            args.display = True
        elif arg in ('-S', '--suppress'):
            args.suppress = True
        elif arg == '--drop':
            i += 1
            if i < len(args_list):
                args.drop = args_list[i]
        elif arg == '--filter':
            i += 1
            if i < len(args_list):
                args.filter = args_list[i]
        elif arg in ('-X', '--hide'):
            args.hide = True
        elif arg in ('-o', '--output'):
            i += 1
            if i < len(args_list):
                args.output = args_list[i]
        elif arg in ('-t', '--time'):
            args.time = True
        elif arg in ('-e', '--email'):
            args.email = True
        elif arg in ('-p', '--phone'):
            args.phone = True
        elif arg in ('-H', '--hash'):
            args.hash = True
        elif arg in ('-i', '--ip-addr'):
            args.ip_addr = True
        elif arg in ('-6', '--ipv6-addr'):
            args.ipv6_addr = True
        elif arg in ('-m', '--mac-addr'):
            args.mac_addr = True
        elif arg in ('-c', '--credit-card'):
            args.credit_card = True
        elif arg in ('-u', '--url'):
            args.url = True
        elif arg in ('-F', '--files'):
            args.files = True
        elif arg in ('-b', '--bitcoin'):
            args.bitcoin = True
        elif arg in ('-a', '--aws'):
            args.aws = True
        elif arg in ('-g', '--google'):
            args.google = True
        elif arg in ('-d', '--dns'):
            args.dns = True
        elif arg in ('-s', '--social'):
            args.social = True
        elif arg.startswith('-') and not arg.startswith('--') and len(arg) > 1:
            # Handle combined short flags like -eCT
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch == 'h':
                    args.help = True
                elif ch == 'V':
                    args.version = True
                elif ch == 'C':
                    args.clean = True
                elif ch == 'l':
                    args.line = True
                elif ch == 'T':
                    args.thorough = True
                elif ch == 'D':
                    args.display = True
                elif ch == 'S':
                    args.suppress = True
                elif ch == 'X':
                    args.hide = True
                elif ch == 't':
                    args.time = True
                elif ch == 'e':
                    args.email = True
                elif ch == 'p':
                    args.phone = True
                elif ch == 'H':
                    args.hash = True
                elif ch == 'i':
                    args.ip_addr = True
                elif ch == '6':
                    args.ipv6_addr = True
                elif ch == 'm':
                    args.mac_addr = True
                elif ch == 'c':
                    args.credit_card = True
                elif ch == 'u':
                    args.url = True
                elif ch == 'F':
                    args.files = True
                elif ch == 'b':
                    args.bitcoin = True
                elif ch == 'a':
                    args.aws = True
                elif ch == 'g':
                    args.google = True
                elif ch == 'd':
                    args.dns = True
                elif ch == 's':
                    args.social = True
                elif ch == 'f':
                    # -f needs next argument
                    rest = arg[j+1:]
                    if rest:
                        args.file = rest
                    else:
                        i += 1
                        if i < len(args_list):
                            args.file = args_list[i]
                    break
                elif ch == 'o':
                    # -o needs next argument
                    rest = arg[j+1:]
                    if rest:
                        args.output = rest
                    else:
                        i += 1
                        if i < len(args_list):
                            args.output = args_list[i]
                    break
                j += 1

        i += 1

    return args


def main():
    args = parse_args()

    if args.version:
        load_plugins()
        print(f"DataSurgeon: https://github.com/Drew-Alleman/DataSurgeon {VERSION}")
        return

    if args.help:
        load_plugins()
        print(HELP_TEXT)
        return

    # Load plugins
    plugins = load_plugins()

    # Handle plugin management commands
    if args.list:
        plugins2 = load_plugins()
        if plugins2 is None or len(plugins2) == 0:
            print(f"No plugins found. Plugin File: {PLUGIN_PATH}")
            sys.exit(1)
        for plugin in plugins2:
            print(plugin['name'])
        return

    start_time = time.time() if args.time else None

    surgeon = DataSurgeon(args)

    try:
        if args.directory:
            if not os.path.isdir(args.directory):
                return
            for root, dirs, files in os.walk(args.directory):
                dirs.sort()
                for fname in sorted(files):
                    filepath = os.path.join(root, fname)
                    try:
                        with open(filepath, 'r', errors='replace') as f:
                            surgeon.process_stream(f, filepath)
                    except Exception as e:
                        if not args.ignore:
                            print(f"[-] Error reading {filepath}: {e}")
        elif args.file:
            if not os.path.exists(args.file):
                if not args.ignore:
                    print(f"[-] File not found: {args.file}")
                sys.exit(1)
            try:
                with open(args.file, 'r', errors='replace') as f:
                    surgeon.process_stream(f, args.file)
            except Exception as e:
                if not args.ignore:
                    print(f"[-] Error reading {args.file}: {e}")
                sys.exit(1)
        else:
            if not args.suppress:
                print("[*] Reading standard input. If you meant to analyze a file use 'ds -f <FILE>' (ctrl+c to exit)")
            surgeon.process_stream(sys.stdin, "")
    finally:
        surgeon.close()

    if start_time is not None:
        elapsed = time.time() - start_time
        hours = int(elapsed // 3600)
        minutes = int((elapsed % 3600) // 60)
        seconds = int(elapsed % 60)
        print(f"[*] Time elapsed: {hours:02d}h:{minutes:02d}m:{seconds:02d}s")


if __name__ == '__main__':
    main()
